input.command:
mkdir -p src scripts && cat > package.json <<'EOF'
{
  "name": "living-garden",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "scripts": {
    "dev": "vite --port 9236 --strictPort",
    "build": "tsc --noEmit && vite build",
    "preview": "vite preview --port 9236 --strictPort",
    "typecheck": "tsc --noEmit",
    "sim": "node --experimental-strip-types --no-warnings scripts/headless.ts"
  },
  "devDependencies": {
    "typescript": "^5.6.0",
    "vite": "^6.0.0"
  }
}
EOF
cat > tsconfig.json <<'EOF'
{
  "compilerOptions": {
    "target": "ES2022",
    "module": "ESNext",
    "moduleResolution": "bundler",
    "lib": ["ES2022", "DOM", "DOM.Iterable"],
    "strict": true,
    "noEmit": true,
    "allowImportingTsExtensions": true,
    "verbatimModuleSyntax": true,
    "erasableSyntaxOnly": true,
    "skipLibCheck": true,
    "types": []
  },
  "include": ["src", "scripts"]
}
EOF
cat > vite.config.ts <<'EOF'
import { defineConfig } from 'vite';

export default defineConfig({
  server: { port: 9236, strictPort: true },
  preview: { port: 9236, strictPort: true },
});
EOF
rtk pnpm install 2>&1 | tail -5

